use crate::theme::{Theme, ThemeExt};
use gpui::prelude::{IntoElement, ParentElement, RenderOnce, Styled};
use gpui::{App, Div, Rgba, SharedString, Window, div};

mod code;
mod heading;
mod link;
mod misc;
mod text_size;
mod text_weight;

pub use code::Code;
pub use heading::Heading;
pub use link::Link;
pub use misc::code_text_color;
pub use text_size::TextSize;
pub use text_weight::TextWeight;
/// A styled text component
#[derive(IntoElement)]
pub struct Text {
    content: SharedString,
    size: TextSize,
    weight: TextWeight,
    color: Option<Rgba>,
    muted: bool,
    truncate: bool,
    theme: Option<Theme>,
}

impl Text {
    /// Create new text
    pub fn new(content: impl Into<SharedString>) -> Self {
        Self {
            content: content.into(),
            size: TextSize::default(),
            weight: TextWeight::default(),
            color: None,
            muted: false,
            truncate: false,
            theme: None,
        }
    }

    /// Eyebrow label — small, bold, uppercase-convention accent text used above
    /// cards and sections (e.g. "RECORDING NAME", "SAVE LOCATION").
    ///
    /// Produces `Xs + Bold`. Callers typically pair it with
    /// `.color(theme.accent)` and pass content in uppercase. Having a single
    /// constructor prevents the eyebrow pattern from drifting into
    /// compressed-header territory (where similar `Xs + Bold` usage should
    /// instead be `section_header`).
    pub fn eyebrow(content: impl Into<SharedString>) -> Self {
        Self::new(content)
            .size(TextSize::Xs)
            .weight(TextWeight::Bold)
    }

    /// Section header inside a panel, card, or dialog — the standard
    /// body-prominence heading one level below a screen/dialog title.
    ///
    /// Produces `Md + Semibold`. Use this instead of building the same
    /// combination by hand so the whole app stays aligned if the convention
    /// later shifts (e.g. to `Lg`).
    pub fn section_header(content: impl Into<SharedString>) -> Self {
        Self::new(content)
            .size(TextSize::Md)
            .weight(TextWeight::Semibold)
    }

    /// Body text — the default paragraph / description size.
    ///
    /// Produces `Md + Normal`. Equivalent to `Text::new(..)` today (since
    /// `Md` is the default size and `Normal` the default weight) but named
    /// explicitly so intent is legible in call sites.
    pub fn body(content: impl Into<SharedString>) -> Self {
        Self::new(content).size(TextSize::Md)
    }

    /// Inline form-field label or table-column header.
    ///
    /// Produces `Sm + Medium`. Smaller than body so labels read as secondary
    /// to the value they describe; medium weight keeps them distinguishable
    /// from surrounding body text.
    pub fn label(content: impl Into<SharedString>) -> Self {
        Self::new(content)
            .size(TextSize::Sm)
            .weight(TextWeight::Medium)
    }

    /// Caption / helper text — field hints, timestamps, unit suffixes, and
    /// other tertiary info.
    ///
    /// Produces `Xs + Normal + muted`. The muted color comes from
    /// `theme.text_muted`, so callers don't need to pass a theme.
    pub fn caption(content: impl Into<SharedString>) -> Self {
        Self::new(content).size(TextSize::Xs).muted(true)
    }

    /// Selectable option label — Xs with weight that flips between Semibold
    /// (when selected) and Normal (when not). Used for radio-button-style
    /// choice rows in dense lists where the size hierarchy is already
    /// established by the surrounding layout (e.g. a column of options each
    /// paired with an Xs description).
    ///
    /// Produces `Xs + (Semibold | Normal)`. Caller chains `.color(...)` to
    /// pick a theme-appropriate color (typically `theme.label_color`).
    /// Captures the selection-state pattern that the typography drift guard
    /// otherwise leaves as the explicit
    /// `weight(if is_selected { Semibold } else { Normal })` form.
    pub fn selectable(content: impl Into<SharedString>, is_selected: bool) -> Self {
        Self::new(content)
            .size(TextSize::Xs)
            .weight(if is_selected {
                TextWeight::Semibold
            } else {
                TextWeight::Normal
            })
    }

    /// Set theme
    pub fn with_theme(mut self, theme: Theme) -> Self {
        self.theme = Some(theme);
        self
    }

    /// Set size
    pub fn size(mut self, size: TextSize) -> Self {
        self.size = size;
        self
    }

    /// Set weight
    pub fn weight(mut self, weight: TextWeight) -> Self {
        self.weight = weight;
        self
    }

    /// Set custom color
    pub fn color(mut self, color: Rgba) -> Self {
        self.color = Some(color);
        self
    }

    /// Make text muted (secondary color)
    pub fn muted(mut self, muted: bool) -> Self {
        self.muted = muted;
        self
    }

    /// Truncate with ellipsis
    pub fn truncate(mut self, truncate: bool) -> Self {
        self.truncate = truncate;
        self
    }

    /// Read-only view of the current size / weight / muted flag.
    ///
    /// Intended primarily for tests that pin the state produced by the
    /// semantic constructors (`eyebrow`, `section_header`, `body`, `label`,
    /// `caption`). Existence of a value-returning accessor avoids collision
    /// with the `size(...)` / `weight(...)` / `muted(...)` builder setters.
    pub fn preset_style(&self) -> (TextSize, TextWeight, bool) {
        (self.size, self.weight, self.muted)
    }

    /// Build into element with theme from App context
    pub fn build_with_cx(self, cx: &App) -> Div {
        let theme = self.theme.clone().unwrap_or_else(|| cx.theme());
        self.build_with_theme(&theme)
    }

    /// Build into element with explicit theme
    pub fn build_with_theme(self, theme: &Theme) -> Div {
        let text_color = if let Some(color) = self.color {
            color
        } else if self.muted {
            theme.text_muted
        } else {
            theme.text_secondary
        };

        let mut text = div()
            .font_family(theme.font_family.clone())
            .text_color(text_color)
            .font_weight(self.weight.to_font_weight());

        // Apply size via the canonical `TextSize::to_rems()` mapping. Keeping a
        // single source of truth avoids the earlier bug where `Md` silently
        // aliased `text_sm()` instead of `text_base()`, making default-sized
        // text one step smaller than intended across the app.
        text = text.text_size(self.size.to_rems());

        if self.truncate {
            text = text.overflow_hidden().whitespace_nowrap();
        }

        text.child(self.content)
    }

    /// Build into element (uses default dark theme colors for backwards compatibility)
    pub fn build(self) -> Div {
        let theme = self.theme.clone().unwrap_or_else(Theme::dark);
        self.build_with_theme(&theme)
    }
}

impl RenderOnce for Text {
    fn render(self, _window: &mut Window, cx: &mut App) -> impl IntoElement {
        let theme = self.theme.clone().unwrap_or_else(|| cx.theme());
        self.build_with_theme(&theme)
    }
}
